    audioUrl: '/audio/radio/animal-news/animal-news-d2.mp3',
    subtitles: [
      { start: 0, end: 2, ko: '안녕하십니까, 동물시 뉴스입니다.', zh: '大家好，这里是动物城新闻。', zhEn: 'Hello everyone, this is Animal City News.' },
      { start: 1.95, end: 4.68, ko: '지금부터 낮 열두 시 소식을 전해 드리겠습니다.', zh: '现在为您播报正午十二点的新闻。', zhEn: 'We now bring you the news at noon, 12 o\'clock.' },
      { start: 4.63, end: 7.24, ko: '오늘도 알찬 소식으로 찾아왔습니다.', zh: '今天也为您带来充实的消息。', zhEn: 'Today we also have a full lineup of news for you.' },
      { start: 7.19, end: 8.8, ko: '오늘의 첫 소식입니다.', zh: '今天的第一条新闻。', zhEn: 'Our first story today.' },
      { start: 8.75, end: 12.3, ko: '이번 주말, 동물시에서 여름 축제가 열립니다.', zh: '本周末，动物城将举办夏日庆典。', zhEn: 'This weekend, Animal City will host a summer festival.' },
      { start: 12.25, end: 15.06, ko: '축제 이름은 "반딧불이 여름 축제"입니다.', zh: '庆典的名字叫"萤火虫夏日庆典"。', zhEn: 'The festival is called the "Firefly Summer Festival."' },
      { start: 15.01, end: 17.86, ko: '마을 광장에서 주말 저녁에 시작됩니다.', zh: '将于周末傍晚在村子广场开始。', zhEn: 'It will start at the village square on the weekend evening.' },
      { start: 17.81, end: 20.58, ko: '준비 위원회는 마지막 점검을 하고 있습니다.', zh: '筹备委员会正在做最后的检查。', zhEn: 'The organizing committee is doing final checks.' },
      { start: 20.53, end: 23.46, ko: '광장에는 벌써 예쁜 등불이 걸렸습니다.', zh: '广场上已经挂起了漂亮的灯笼。', zhEn: 'Beautiful lanterns are already hung in the square.' },
      { start: 23.41, end: 26.6, ko: '올해는 먹거리 가게가 스무 곳이나 참여합니다.', zh: '今年有多达二十家美食摊参与。', zhEn: 'This year, as many as twenty food stalls are participating.' },
      { start: 26.55, end: 29.78, ko: '다람쥐 상인은 도토리 과자를 준비했다고 합니다.', zh: '松鼠商贩说准备了橡子饼干。', zhEn: 'The squirrel vendor said they prepared acorn cookies.' },
      { start: 29.73, end: 32.78, ko: '저녁 여덟 시에는 반딧불이 구경 시간이 있습니다.', zh: '晚上八点有观赏萤火虫的时间。', zhEn: 'There\'s a firefly viewing time at 8 PM.' },
      { start: 33.52, end: 35.96, ko: '강가에서 수많은 반딧불이를 볼 수 있습니다.', zh: '在河边可以看到无数的萤火虫。', zhEn: 'You can see countless fireflies by the river.' },
      { start: 35.91, end: 39.18, ko: '주최 측은 많은 참여를 부탁드린다고 전했습니다.', zh: '主办方表示，恳请大家踊跃参与。', zhEn: 'The organizers ask everyone to participate enthusiastically.' },
      { start: 39.13, end: 40.7, ko: '다음 소식입니다.', zh: '接下来是下一条新闻。', zhEn: 'Next up is another news story.' },
      { start: 40.65, end: 43.52, ko: '마을 도서관이 주말 동안 문을 닫습니다.', zh: '村子图书馆将在周末期间闭馆。', zhEn: 'The village library will be closed over the weekend.' },
      { start: 43.47, end: 45.7, ko: '축제 준비를 돕기 위해서입니다.', zh: '这是为了协助庆典的筹备工作。', zhEn: 'This is to help with festival preparations.' },
      { start: 45.65, end: 48.46, ko: '책 반납은 축제가 끝난 뒤로 미뤄졌습니다.', zh: '还书日期推迟到庆典结束之后。', zhEn: 'The book return date is postponed to after the festival ends.' },
      { start: 48.41, end: 50.7, ko: '이용에 불편이 없으시길 바랍니다.', zh: '希望不会给您的使用带来不便。', zhEn: 'We hope this doesn\'t cause any inconvenience.' },
      { start: 50.65, end: 52.32, ko: '이번에는 날씨입니다.', zh: '接下来是天气。', zhEn: 'Next is the weather.' },
      { start: 52.27, end: 54.46, ko: '주말 내내 맑고 따뜻하겠습니다.', zh: '整个周末都将晴朗温暖。', zhEn: 'It\'ll be sunny and warm all weekend.' },
      { start: 54.41, end: 57.16, ko: '낮 기온은 이십팔 도까지 오르겠습니다.', zh: '白天气温将升至二十八度。', zhEn: 'Daytime temperatures will rise to 28 degrees.' },
      { start: 57.58, end: 59.68, ko: '저녁에는 바람이 선선하게 불겠습니다.', zh: '傍晚将吹起凉爽的风。', zhEn: 'A cool breeze will blow in the evening.' },
      { start: 60.14, end: 62.56, ko: '축제를 즐기기에 아주 좋은 날씨입니다.', zh: '是非常适合享受庆典的好天气。', zhEn: 'It\'s perfect weather for enjoying the festival.' },
      { start: 62.8, end: 64.74, ko: '다만 물을 자주 드시기 바랍니다.', zh: '不过请记得勤喝水。', zhEn: 'But remember to drink plenty of water.' },
      { start: 64.94, end: 66.72, ko: '이상으로 오늘 소식을 마치겠습니다.', zh: '以上就是今天的新闻。', zhEn: 'That\'s all for today\'s news.' },
      { start: 67.44, end: 69.84, ko: '내일도 정확한 소식으로 찾아뵙겠습니다.', zh: '明天也将为您带来准确的消息。', zhEn: 'We\'ll bring you accurate news again tomorrow.' },
      { start: 70.24, end: 72.75, ko: '지금까지 동물시 뉴스였습니다.', zh: '以上是动物城新闻。', zhEn: 'That\'s the news from Animal City.' },
    ],
    vocab: [
      { ko: '축제', pos: '명사', zh: '庆典、节日', zhEn: 'festival, holiday', example: '주말에 축제가 열립니다.', exampleZh: '周末举办庆典。', exampleZhEn: 'A festival is held on the weekend.' },
      { ko: '열리다', pos: '동사', zh: '举办、举行', zhEn: 'to hold, to host', example: '광장에서 축제가 열립니다.', exampleZh: '在广场举办庆典。', exampleZhEn: 'A festival is held in the square.' },
      { ko: '광장', pos: '명사', zh: '广场', zhEn: 'plaza', example: '마을 광장에 모였습니다.', exampleZh: '在村子广场集合了。', exampleZhEn: 'We gathered in the village square.' },
      { ko: '반딧불이', pos: '명사', zh: '萤火虫', zhEn: 'firefly', example: '강가에서 반딧불이를 봤습니다.', exampleZh: '在河边看到了萤火虫。', exampleZhEn: 'I saw fireflies by the river.' },
      { ko: '등불', pos: '명사', zh: '灯笼、灯火', zhEn: 'lantern, light', example: '광장에 등불이 걸렸습니다.', exampleZh: '广场上挂起了灯笼。', exampleZhEn: 'Lanterns were hung up in the square.' },
      { ko: '점검', pos: '명사', zh: '检查、检点', zhEn: 'check, inspect', example: '마지막 점검을 했습니다.', exampleZh: '做了最后的检查。', exampleZhEn: 'Did a final check.' },
      { ko: '주최 측', pos: '명사', zh: '主办方', zhEn: 'organizer', example: '주최 측이 참여를 부탁했습니다.', exampleZh: '主办方请求大家参与。', exampleZhEn: 'The organizers ask everyone to participate.' },
      { ko: '선선하다', pos: '형용사', zh: '凉爽', zhEn: 'Cool', example: '저녁 바람이 선선합니다.', exampleZh: '傍晚的风很凉爽。', exampleZhEn: 'The evening breeze is cool.' },
    ],
