        audioUrl: '/audio/radio/animal-news/animal-news-d15.mp3',
        subtitles: [
            { start: 0, end: 3.02, ko: '안녕하십니까, 동물시 뉴스의 늑대 아나운서입니다.', zh: '大家好，这里是动物城新闻，我是狼主播。', zhEn: 'Hello everyone, this is Animal City News, I\'m your host Wolf.' },
            { start: 3.32, end: 6.46, ko: '오늘도 동물시의 따뜻한 소식을 전해 드리겠습니다.', zh: '今天也为大家带来动物城温暖的消息。', zhEn: 'Today, we bring you heartwarming news from Animal Town.' },
            { start: 6.76, end: 7.91, ko: '첫 번째 소식입니다.', zh: '第一条新闻。', zhEn: 'First story.' },
            { start: 8.21, end: 11.58, ko: '어제 오후, 버스 정류장에서 작은 소동이 있었습니다.', zh: '昨天下午，公交站发生了一件小事。', zhEn: 'Yesterday afternoon, a small incident happened at the bus stop.' },
            { start: 11.88, end: 14.48, ko: '너구리 아저씨가 지갑을 잃어버렸다고 합니다.', zh: '据说浣熊大叔弄丢了钱包。', zhEn: 'It\'s said that Uncle Raccoon lost his wallet.' },
            { start: 14.78, end: 17.8, ko: '그때 지나가던 다람쥐가 지갑을 발견했습니다.', zh: '这时路过的松鼠发现了钱包。', zhEn: 'Just then, a passing squirrel spotted the wallet.' },
            { start: 18.1, end: 21.42, ko: '다람쥐는 곧바로 정류장 사무실에 지갑을 맡겼습니다.', zh: '松鼠立刻把钱包交到了车站办公室。', zhEn: 'The squirrel immediately turned the wallet in to the station office.' },
            { start: 21.72, end: 24.58, ko: '너구리 아저씨는 무사히 지갑을 돌려받았습니다.', zh: '浣熊大叔顺利地拿回了钱包。', zhEn: 'Uncle Raccoon got his wallet back safely.' },
            { start: 24.88, end: 28.07, ko: '아저씨는 다람쥐에게 진심으로 고맙다고 말했습니다.', zh: '大叔真心向松鼠道了谢。', zhEn: 'He sincerely thanked the squirrel.' },
            { start: 28.37, end: 30.84, ko: '작은 친절이 큰 감동을 주는 하루였습니다.', zh: '这是小小善意带来大感动的一天。', zhEn: 'It was a day when small kindnesses brought great warmth.' },
            { start: 31.14, end: 32.88, ko: '이어서 두 번째 소식입니다.', zh: '接下来是第二条新闻。', zhEn: 'Next up is the second news story.' },
            { start: 33.18, end: 36.68, ko: '이번 주말에 한강 공원에서 작은 음악회가 열립니다.', zh: '这个周末，汉江公园将举办一场小型音乐会。', zhEn: 'This weekend, a small concert will be held at Han River Park.' },
            { start: 36.98, end: 39.58, ko: '부엉이 합창단이 저녁 무대에 오른다고 합니다.', zh: '据说猫头鹰合唱团将登上傍晚的舞台。', zhEn: 'The Owl Choir is said to take the stage in the evening.' },
            { start: 39.88, end: 43.15, ko: '입장료는 무료이며 누구나 참여할 수 있습니다.', zh: '入场免费，任何人都可以参加。', zhEn: 'Admission is free, and anyone can join.' },
            { start: 43.45, end: 45.93, ko: '돗자리와 간식을 준비해 오시면 좋겠습니다.', zh: '建议大家带上野餐垫和小零食前来。', zhEn: 'We recommend bringing a picnic mat and some snacks.' },
            { start: 46.23, end: 48.27, ko: '가족과 함께 즐기기 좋은 행사입니다.', zh: '这是适合全家一起享受的活动。', zhEn: 'This is an event the whole family can enjoy.' },
            { start: 48.57, end: 50.95, ko: '많은 주민들의 관심이 기대됩니다.', zh: '期待众多居民的关注。', zhEn: 'We look forward to the attention of many residents.' },
            { start: 51.25, end: 53.29, ko: '마지막으로 날씨를 전해 드리겠습니다.', zh: '最后为大家播报天气。', zhEn: 'Finally, here\'s the weather report.' },
            { start: 53.59, end: 57.01, ko: '요즘 아침저녁으로 바람이 제법 선선해졌습니다.', zh: '最近早晚的风变得相当凉爽。', zhEn: 'Recently, the winds in the morning and evening have turned quite cool.' },
            { start: 57.31, end: 60.04, ko: '낮에는 맑고 하늘이 높아 나들이하기 좋습니다.', zh: '白天晴朗、天空高远，很适合出游。', zhEn: 'The days are clear with high skies, perfect for going out.' },
            { start: 60.34, end: 63.06, ko: '오후에는 얇은 겉옷을 챙기시길 권합니다.', zh: '建议下午带上一件薄外套。', zhEn: 'We suggest bringing a light jacket in the afternoon.' },
            { start: 63.36, end: 65.36, ko: '주말까지 큰 비 소식은 없겠습니다.', zh: '到周末为止没有大雨的消息。', zhEn: 'There\'s no news of heavy rain until the weekend.' },
            { start: 65.66, end: 68.52, ko: '건조한 날씨가 이어지니 물을 자주 드시기 바랍니다.', zh: '天气持续干燥，请大家多喝水。', zhEn: 'The dry weather continues, so please drink plenty of water.' },
            { start: 68.82, end: 71.16, ko: '이상으로 오늘의 소식을 마치겠습니다.', zh: '以上就是今天的新闻。', zhEn: 'That\'s all for today\'s news.' },
            { start: 71.46, end: 74.32, ko: '동물시 주민 여러분, 편안한 하루 보내십시오.', zh: '动物城的居民们，祝大家度过舒适的一天。', zhEn: 'Residents of Animal Town, have a comfortable day.' },
            { start: 74.62, end: 78.11, ko: '지금까지 늑대 아나운서였습니다. 감사합니다.', zh: '以上是狼主播的播报，谢谢大家。', zhEn: 'That was the report from Anchor Wolf, thank you all.' },
        ],
