        audioUrl: '/audio/radio/animal-news/animal-news-d17.mp3',
        subtitles: [
            { start: 0, end: 3.54, ko: '안녕하십니까, 동물시 뉴스의 늑대 아나운서입니다.', zh: '大家好，我是动物城新闻的狼主播。', zhEn: 'Hello everyone, I\'m Wolf, the anchor for Animal City News.' },
            { start: 3.84, end: 6.73, ko: '오늘 낮 소식을 지금부터 전해 드리겠습니다.', zh: '现在开始为大家播报今天中午的消息。', zhEn: 'Now, let\'s bring you today\'s midday news.' },
            { start: 7.03, end: 9.54, ko: '첫 소식은 시장 골목에서 들어왔습니다.', zh: '第一条新闻来自市场小巷。', zhEn: 'Our first story comes from Market Alley.' },
            { start: 9.84, end: 12.52, ko: '캥거루 아주머니의 식당 앞에서 있었던 일입니다.', zh: '这是发生在袋鼠阿姨餐厅门前的事。', zhEn: 'This happened in front of Aunt Kangaroo\'s restaurant.' },
            { start: 12.82, end: 15.42, ko: '길을 잃은 아기 햄스터가 울고 있었다고 합니다.', zh: '据说一只迷路的小仓鼠正在哭。', zhEn: 'A lost little hamster was reportedly crying.' },
            { start: 15.72, end: 18.96, ko: '아주머니는 아기를 식당 안으로 데려가 달래 주었습니다.', zh: '阿姨把小仓鼠带进餐厅安慰了它。', zhEn: 'The aunt brought the hamster into the restaurant to comfort it.' },
            { start: 19.26, end: 22.25, ko: '따뜻한 국물을 먹이며 부모를 기다렸습니다.', zh: '一边喂它喝热汤，一边等它的父母。', zhEn: 'She fed it hot soup while waiting for its parents.' },
            { start: 22.55, end: 25.53, ko: '한참 뒤 걱정하던 부모가 아기를 찾아왔습니다.', zh: '过了好一会儿，担心的父母找了过来。', zhEn: 'After a while, its worried parents came looking for it.' },
            { start: 25.83, end: 28.94, ko: '온 가족이 아주머니에게 깊이 감사드렸습니다.', zh: '一家人向阿姨深深致谢。', zhEn: 'The family thanked the aunt deeply.' },
            { start: 29.24, end: 31.33, ko: '이웃의 따뜻함이 빛난 하루였습니다.', zh: '这是邻里温情闪光的一天。', zhEn: 'It was a day when neighborly warmth shone through.' },
            { start: 31.63, end: 33.46, ko: '두 번째 소식으로 넘어가겠습니다.', zh: '接着播报第二条新闻。', zhEn: 'Now, moving on to the second story.' },
            { start: 33.76, end: 36.83, ko: '이번 주말 광장에서 가을 벼룩시장이 열립니다.', zh: '这个周末广场将举办秋季跳蚤市场。', zhEn: 'An autumn flea market will be held at the plaza this weekend.' },
            { start: 37.13, end: 40.11, ko: '주민들이 직접 만든 물건을 사고팔 수 있습니다.', zh: '居民们可以买卖自己亲手做的东西。', zhEn: 'Residents can buy and sell things they\'ve made by hand.' },
            { start: 40.41, end: 43.05, ko: '손수 뜬 목도리와 수제 잼이 인기라고 합니다.', zh: '据说亲手织的围巾和手工果酱很受欢迎。', zhEn: 'Hand-knitted scarves and homemade jams are said to be quite popular.' },
            { start: 43.35, end: 45.98, ko: '판매 수익의 일부는 이웃 돕기에 쓰인다고 합니다.', zh: '据说部分销售收入将用于帮助邻里。', zhEn: 'Part of the sales proceeds will go toward helping neighbors.' },
            { start: 46.28, end: 48.63, ko: '따뜻한 마음이 모이는 자리가 되겠습니다.', zh: '这将成为汇聚温暖心意的场合。', zhEn: 'It\'ll be a gathering of warm hearts.' },
            { start: 48.93, end: 50.59, ko: '이제 오늘의 날씨입니다.', zh: '现在是今天的天气。', zhEn: 'Now for today\'s weather.' },
            { start: 50.89, end: 52.81, ko: '하루 종일 구름이 많이 끼겠습니다.', zh: '一整天都会多云。', zhEn: 'It\'ll be cloudy all day.' },
            { start: 53.11, end: 55.87, ko: '늦은 오후부터 가랑비가 조금 내리겠습니다.', zh: '从傍晚开始会下一点毛毛雨。', zhEn: 'A light drizzle will start in the evening.' },
            { start: 56.17, end: 59.02, ko: '외출하실 때는 우산을 꼭 챙기시기 바랍니다.', zh: '外出时请务必带上伞。', zhEn: 'Be sure to bring an umbrella when you go out.' },
            { start: 59.32, end: 61.45, ko: '기온은 어제보다 조금 낮아지겠습니다.', zh: '气温会比昨天略低一些。', zhEn: 'Temperatures will be slightly lower than yesterday.' },
            { start: 61.75, end: 64.35, ko: '감기 걸리지 않도록 옷을 따뜻하게 입으십시오.', zh: '为了不感冒，请大家穿暖一点。', zhEn: 'Dress warmly to avoid catching a cold.' },
            { start: 64.65, end: 67.03, ko: '밤에는 비가 그치고 별을 볼 수 있겠습니다.', zh: '夜里雨会停，能看到星星。', zhEn: 'The rain will stop at night, and you\'ll be able to see the stars.' },
            { start: 67.33, end: 69.55, ko: '이상으로 오늘의 소식을 마치겠습니다.', zh: '以上就是今天的新闻。', zhEn: 'That\'s all for today\'s news.' },
            { start: 69.85, end: 73.39, ko: '동물시 주민 여러분, 포근한 오후 보내십시오.', zh: '动物城的居民们，祝大家度过温暖的下午。', zhEn: 'Residents of Animal Town, have a warm afternoon.' },
            { start: 73.69, end: 77.31, ko: '지금까지 늑대 아나운서였습니다. 감사합니다.', zh: '以上是狼主播的播报，谢谢大家。', zhEn: 'That was the report from Anchor Wolf, thank you all.' },
        ],
