        subtitles: [
            { start: 0, end: 3.37, ko: '안녕하십니까, 동물시 뉴스의 늑대 아나운서입니다.', zh: '大家好，这里是动物城新闻，我是狼主播。', zhEn: 'Hello everyone, this is Animal City News, I\'m your host Wolf.' },
            { start: 3.67, end: 6.4, ko: '오늘도 반가운 소식으로 하루를 시작하겠습니다.', zh: '今天也用令人高兴的消息开始一天。', zhEn: 'Start the day with good news today too.' },
            { start: 6.7, end: 8.23, ko: '첫 번째 소식입니다.', zh: '第一条新闻。', zhEn: 'First story.' },
            { start: 8.53, end: 11.8, ko: '캥거루 아주머니의 식당이 오늘 오 주년을 맞이했습니다.', zh: '袋鼠阿姨的餐厅今天迎来了五周年。', zhEn: 'Auntie Kangaroo\'s restaurant celebrates its fifth anniversary today.' },
            { start: 12.1, end: 16.62, ko: '아주머니는 감사의 뜻으로 따뜻한 국밥을 이웃에게 대접하셨습니다.', zh: '阿姨为表达感谢，招待邻居们喝了热汤饭。', zhEn: 'To show her gratitude, she treated the neighbors to hot soup and rice.' },
            { start: 16.92, end: 20.16, ko: '오랜 단골손님들이 찾아와 함께 축하해 주었습니다.', zh: '许多老主顾也前来一同庆祝。', zhEn: 'Many regulars also came to celebrate together.' },
            { start: 20.46, end: 23.48, ko: '한 그릇의 정성이 오 년 동안 마을을 이어 주었습니다.', zh: '一碗饭的用心维系了小镇五年。', zhEn: 'The care in a single bowl of rice has sustained the town for five years.' },
            { start: 23.78, end: 24.93, ko: '두 번째 소식입니다.', zh: '第二条新闻。', zhEn: 'Second story.' },
            { start: 25.23, end: 28.72, ko: '다음 주에 동물시 골목에서 가을 음악회가 열릴 예정입니다.', zh: '下周动物城的巷子里将举办秋季音乐会。', zhEn: 'Next week, an autumn concert will be held in the alleys of Animal Town.' },
            { start: 29.02, end: 31.88, ko: '햄스터 악단이 부드러운 곡을 준비하고 있다고 합니다.', zh: '仓鼠乐团正在准备柔和的曲子。', zhEn: 'The hamster band is preparing soft melodies.' },
            { start: 32.18, end: 34.9, ko: '저녁 골목을 걸으며 음악을 즐길 수 있겠습니다.', zh: '可以一边走在傍晚的巷子里一边欣赏音乐。', zhEn: 'You can enjoy the music while strolling through the evening alleys.' },
            { start: 35.2, end: 38.19, ko: '누구나 자유롭게 참여할 수 있으니 많이 오시기 바랍니다.', zh: '任何人都可自由参加，欢迎踊跃前来。', zhEn: 'Anyone can join freely—everyone is welcome.' },
            { start: 38.49, end: 40.36, ko: '세 번째 소식은 날씨입니다.', zh: '第三条新闻是天气。', zhEn: 'The third news item is the weather.' },
            { start: 40.66, end: 43.17, ko: '오늘은 하루 종일 구름이 조금 끼겠습니다.', zh: '今天一整天会有些多云。', zhEn: 'It will be partly cloudy throughout the day.' },
            { start: 43.47, end: 46.23, ko: '비 소식은 없지만 습도가 조금 높겠습니다.', zh: '没有降雨消息，但湿度会稍高。', zhEn: 'No rain is expected, but humidity will be a bit high.' },
            { start: 46.53, end: 49.47, ko: '기온은 어제와 비슷하여 활동하기에 무난하겠습니다.', zh: '气温与昨天相近，适合活动。', zhEn: 'Temperatures are similar to yesterday, perfect for activities.' },
            { start: 49.77, end: 52.75, ko: '저녁에는 구름이 걷히며 별을 볼 수 있겠습니다.', zh: '傍晚云会散去，可以看到星星。', zhEn: 'The clouds will clear by evening, and you\'ll see the stars.' },
            { start: 53.05, end: 55.27, ko: '가벼운 마음으로 하루를 보내시기 바랍니다.', zh: '祝大家以轻松的心情度过一天。', zhEn: 'Wishing everyone a relaxed day.' },
            { start: 55.57, end: 58.3, ko: '이상으로 오늘의 소식을 모두 전해 드렸습니다.', zh: '以上就是今天的全部消息。', zhEn: 'That\'s all the news for today.' },
            { start: 58.6, end: 61.58, ko: '오랜 세월 한자리를 지키는 일은 참 대단합니다.', zh: '长年守着一个地方真的很了不起。', zhEn: 'Staying in one place for years is truly admirable.' },
            { start: 61.88, end: 64.99, ko: '캥거루 아주머니의 오 주년을 다시 한번 축하드립니다.', zh: '再次祝贺袋鼠阿姨五周年。', zhEn: 'Congratulations again to Auntie Kangaroo on her fifth anniversary.' },
            { start: 65.29, end: 67.67, ko: '지금까지 동물시 뉴스였습니다.', zh: '以上就是动物城新闻。', zhEn: 'That\'s the news from Animal Town.' },
            { start: 67.97, end: 70.14, ko: '늑대 아나운서가 전해 드렸습니다.', zh: '由狼主播为您播报。', zhEn: 'Reported by Wolf the anchor.' },
            { start: 70.44, end: 72.66, ko: '오늘도 맛있는 한 끼 드시기 바랍니다.', zh: '祝大家今天也吃上一顿美味的饭。', zhEn: 'Wishing everyone a delicious meal today too.' },
            { start: 72.96, end: 73.73, ko: '감사합니다.', zh: '谢谢。', zhEn: 'Thank you.' },
        ],
