        subtitles: [
            { start: 0, end: 3.54, ko: '안녕하십니까, 동물시 뉴스의 늑대 아나운서입니다.', zh: '大家好，这里是动物城新闻，我是狼主播。', zhEn: 'Hello everyone, this is Animal City News, I\'m your host Wolf.' },
            { start: 3.84, end: 6.57, ko: '오늘도 마음이 훈훈해지는 소식을 준비했습니다.', zh: '今天也准备了让人心里暖暖的消息。', zhEn: 'Today we have some heartwarming news.' },
            { start: 6.87, end: 8.05, ko: '첫 번째 소식입니다.', zh: '第一条新闻。', zhEn: 'First story.' },
            { start: 8.35, end: 12.36, ko: '토끼 자매가 길 잃은 새끼 고양이를 사흘 만에 집으로 돌려보냈습니다.', zh: '兔子姐妹在三天后把迷路的小猫送回了家。', zhEn: 'The rabbit sisters returned the lost kitten home after three days.' },
            { start: 12.66, end: 16.62, ko: '자매는 마을 곳곳에 작은 안내문을 붙이며 주인을 찾았습니다.', zh: '姐妹俩在小镇各处贴了小告示寻找主人。', zhEn: 'The sisters posted small notices around town to find the owner.' },
            { start: 16.92, end: 20.03, ko: '다시 만난 고양이 가족은 서로를 꼭 껴안았습니다.', zh: '重逢的猫咪一家紧紧抱在一起。', zhEn: 'The reunited cat family hugged each other tightly.' },
            { start: 20.33, end: 23.52, ko: '포기하지 않은 마음이 가족을 다시 이어 주었습니다.', zh: '不放弃的心让一家人重新团聚。', zhEn: 'A never-give-up heart brought the family back together.' },
            { start: 23.82, end: 24.97, ko: '두 번째 소식입니다.', zh: '第二条新闻。', zhEn: 'Second story.' },
            { start: 25.27, end: 29.28, ko: '다음 주 여우 사장님의 카페에서 가을 향기 축제가 열립니다.', zh: '下周狐狸老板的咖啡馆将举办秋香节。', zhEn: 'Next week, Mr. Fox\'s café will host an Autumn Aroma Festival.' },
            { start: 29.58, end: 32.56, ko: '갓 볶은 원두와 계절 차를 맛볼 수 있다고 합니다.', zh: '据说可以品尝刚炒好的咖啡豆和季节茶。', zhEn: 'You can taste freshly roasted coffee beans and seasonal teas.' },
            { start: 32.86, end: 35.54, ko: '작은 음악 공연도 함께 준비되어 있습니다.', zh: '还一起准备了小型音乐演出。', zhEn: 'A small live music performance is also planned.' },
            { start: 35.84, end: 39.04, ko: '따뜻한 향기 속에서 이웃과 이야기 나눠 보시기 바랍니다.', zh: '愿大家在温暖的香气中与邻居畅谈。', zhEn: 'May you all enjoy warm chats with neighbors amidst the cozy aromas.' },
            { start: 39.34, end: 40.9, ko: '세 번째 소식은 날씨입니다.', zh: '第三条新闻是天气。', zhEn: 'The third news item is the weather.' },
            { start: 41.2, end: 43.93, ko: '오늘 오후부터 가랑비가 조금 내리겠습니다.', zh: '今天下午起会下点小雨。', zhEn: 'It\'ll start drizzling a bit this afternoon.' },
            { start: 44.23, end: 47.09, ko: '많은 양은 아니지만 우산을 챙기시면 좋겠습니다.', zh: '雨量不大，但带把伞会更好。', zhEn: 'It won\'t be much, but bringing an umbrella is a good idea.' },
            { start: 47.39, end: 50.41, ko: '비가 그친 뒤에는 공기가 한결 맑아지겠습니다.', zh: '雨停之后空气会清新许多。', zhEn: 'The air will feel much fresher after the rain stops.' },
            { start: 50.71, end: 52.67, ko: '기온은 조금 내려가 선선하겠습니다.', zh: '气温会稍降，变得凉爽。', zhEn: 'The temperature will drop a bit, turning cool.' },
            { start: 52.97, end: 54.54, ko: '감기 조심하시기 바랍니다.', zh: '请小心感冒。', zhEn: 'Be careful not to catch a cold.' },
            { start: 54.84, end: 58.03, ko: '이상으로 오늘의 소식을 모두 전해 드렸습니다.', zh: '以上就是今天的全部消息。', zhEn: 'That\'s all the news for today.' },
            { start: 58.33, end: 61.39, ko: '누군가를 끝까지 찾아 주는 마음이 참 귀합니다.', zh: '愿意坚持到底寻找某人的心真的很珍贵。', zhEn: 'A heart that keeps searching for someone to the very end is truly precious.' },
            { start: 61.69, end: 64.46, ko: '토끼 자매의 따뜻한 마음에 박수를 보냅니다.', zh: '为兔子姐妹温暖的心送上掌声。', zhEn: 'Let\'s give a round of applause for the warm hearts of the rabbit sisters.' },
            { start: 64.76, end: 66.93, ko: '지금까지 동물시 뉴스였습니다.', zh: '以上就是动物城新闻。', zhEn: 'That\'s the news from Animal Town.' },
            { start: 67.23, end: 69.1, ko: '늑대 아나운서가 전해 드렸습니다.', zh: '由狼主播为您播报。', zhEn: 'Reported by Wolf the anchor.' },
            { start: 69.4, end: 72.51, ko: '비 오는 오후, 따뜻하게 보내시기 바랍니다.', zh: '祝大家在下雨的午后过得温暖。', zhEn: 'Wishing everyone a cozy rainy afternoon.' },
            { start: 72.81, end: 73.57, ko: '감사합니다.', zh: '谢谢。', zhEn: 'Thank you.' },
        ],
        vocab: [
            { ko: '안내문', pos: '명사', zh: '告示，说明', zhEn: 'notice, explanation', example: '안내문을 붙였습니다', exampleZh: '贴了告示', exampleZhEn: 'posted a notice' },
            { ko: '껴안다', pos: '동사', zh: '拥抱', zhEn: 'Hug', example: '가족을 껴안았습니다', exampleZh: '拥抱了家人', exampleZhEn: 'hugged family' },
            { ko: '포기하다', pos: '동사', zh: '放弃', zhEn: 'Give up', example: '끝까지 포기하지 않습니다', exampleZh: '到最后也不放弃', exampleZhEn: 'never giving up to the end' },
            { ko: '볶다', pos: '동사', zh: '炒', zhEn: 'to stir-fry', example: '원두를 볶습니다', exampleZh: '炒咖啡豆', exampleZhEn: 'roasting coffee beans' },
            { ko: '가랑비', pos: '명사', zh: '毛毛雨', zhEn: 'drizzle', example: '가랑비가 내립니다', exampleZh: '下着毛毛雨', exampleZhEn: 'drizzling' },
            { ko: '한결', pos: '부사', zh: '更加，格外', zhEn: 'even more, especially', example: '공기가 한결 맑습니다', exampleZh: '空气清新多了', exampleZhEn: 'the air is much fresher' },
            { ko: '선선하다', pos: '형용사', zh: '凉爽', zhEn: 'Cool', example: '날씨가 선선합니다', exampleZh: '天气凉爽', exampleZhEn: 'cool weather' },
            { ko: '귀하다', pos: '형용사', zh: '珍贵', zhEn: 'precious', example: '마음이 귀합니다', exampleZh: '这份心意珍贵', exampleZhEn: 'this kindness is precious' },
        ],
