        audioUrl: '/audio/radio/animal-news/animal-news-d30.mp3',
        subtitles: [
            { start: 0, end: 3.41, ko: '안녕하십니까, 동물시 뉴스의 늑대 아나운서입니다.', zh: '大家好，这里是动物城新闻，我是狼主播。', zhEn: 'Hello everyone, this is Animal City News, I\'m your host Wolf.' },
            { start: 3.71, end: 7.25, ko: '오늘은 이달의 마지막 방송으로 여러분을 찾아뵙습니다.', zh: '今天是本月最后一期节目与大家见面。', zhEn: 'Today is the last episode of this month\'s program.' },
            { start: 7.55, end: 9.12, ko: '첫 번째 소식입니다.', zh: '第一条新闻。', zhEn: 'First story.' },
            { start: 9.42, end: 12.92, ko: '여우 사장님이 한 달 동안 모은 성금을 이웃 쉼터에 전했습니다.', zh: '狐狸老板把一个月来募集的善款送到了邻里避护所。', zhEn: 'Boss Fox delivered the donations collected over the past month to the neighborhood shelter.' },
            { start: 13.22, end: 16.92, ko: '카페를 찾은 손님들이 조금씩 마음을 보탠 결과입니다.', zh: '这是光顾咖啡馆的客人们一点点献出心意的结果。', zhEn: 'This is the result of the café\'s customers giving a little bit of their hearts.' },
            { start: 17.22, end: 20.03, ko: '작은 동전이 모여 큰 온정을 이루었습니다.', zh: '小小的硬币汇聚成了大大的温情。', zhEn: 'Small coins came together to form great warmth.' },
            { start: 20.33, end: 23.31, ko: '나눔은 언제나 마을을 더 단단하게 만듭니다.', zh: '分享总能让小镇更加坚实。', zhEn: 'Sharing always makes the town stronger.' },
            { start: 23.61, end: 24.8, ko: '두 번째 소식입니다.', zh: '第二条新闻。', zhEn: 'Second story.' },
            { start: 25.1, end: 29.53, ko: '다음 주부터 동물시 도서관에서 겨울 이야기 모임이 시작됩니다.', zh: '下周起动物城图书馆将开始冬季故事会。', zhEn: 'Starting next week, the Animal Town Library will begin its winter story time.' },
            { start: 29.83, end: 32.69, ko: '부엉이 관장이 매주 새로운 이야기를 들려준다고 합니다.', zh: '据说猫头鹰馆长每周都会讲一个新故事。', zhEn: 'They say the owl librarian will tell a new story every week.' },
            { start: 32.99, end: 36.31, ko: '추운 계절을 따뜻한 이야기로 채워 보시기 바랍니다.', zh: '愿大家用温暖的故事填满寒冷的季节。', zhEn: 'May everyone fill the cold season with warm stories.' },
            { start: 36.61, end: 38.65, ko: '누구나 편하게 참여하실 수 있습니다.', zh: '任何人都可以轻松参加。', zhEn: 'Anyone can easily join.' },
            { start: 38.95, end: 40.87, ko: '세 번째 소식은 날씨입니다.', zh: '第三条新闻是天气。', zhEn: 'The third news item is the weather.' },
            { start: 41.17, end: 43.9, ko: '오늘은 하늘이 맑고 공기가 차갑겠습니다.', zh: '今天天空晴朗，空气清冷。', zhEn: 'The sky is clear today, and the air is crisp.' },
            { start: 44.2, end: 46.8, ko: '아침에는 서리가 살짝 내릴 수도 있겠습니다.', zh: '早上可能会有薄薄的霜。', zhEn: 'There may be a light frost in the morning.' },
            { start: 47.1, end: 50.08, ko: '낮에는 햇살이 따뜻해 견딜 만하겠습니다.', zh: '白天阳光温暖，尚可承受。', zhEn: 'The daytime sun is warm and bearable.' },
            { start: 50.38, end: 53.4, ko: '이제 완연한 늦가을 날씨로 접어들겠습니다.', zh: '如今将进入十足的深秋天气。', zhEn: 'We\'re now heading into full late-autumn weather.' },
            { start: 53.7, end: 56.17, ko: '따뜻한 차와 함께 몸을 데우시기 바랍니다.', zh: '愿大家就着热茶暖暖身子。', zhEn: 'May everyone warm up with some hot tea.' },
            { start: 56.47, end: 59.33, ko: '이상으로 오늘의 소식을 모두 전해 드렸습니다.', zh: '以上就是今天的全部消息。', zhEn: 'That\'s all the news for today.' },
            { start: 59.63, end: 62.65, ko: '돌아보면 이번 달에도 참 많은 온기가 오갔습니다.', zh: '回望这个月，也有许多暖意在流转。', zhEn: 'Looking back on this month, there\'s been a lot of warmth flowing around.' },
            { start: 62.95, end: 68.61, ko: '잃은 지갑을 찾아 주고, 길 잃은 가족을 이어 주고, 이웃을 도운 여러분 덕분입니다.', zh: '这全靠找回钱包、团聚迷路家人、帮助邻居的各位。', zhEn: 'This is all thanks to those who found lost wallets, reunited lost families, and helped their neighbors.' },
            { start: 68.91, end: 72.33, ko: '한 달 동안 함께해 주셔서 진심으로 감사드립니다.', zh: '衷心感谢大家这一个月的相伴。', zhEn: 'Thank you all so much for being with us this past month.' },
            { start: 72.63, end: 75.99, ko: '다음 달에도 변함없이 따뜻한 소식으로 찾아뵙겠습니다.', zh: '下个月也将一如既往用温暖的消息与大家见面。', zhEn: 'Next month, we\'ll be back with warm messages as always.' },
            { start: 76.29, end: 79.74, ko: '지금까지 동물시 뉴스, 늑대 아나운서였습니다.', zh: '以上就是动物城新闻，我是狼主播。', zhEn: 'That\'s all for Animal City News. I\'m Wolf Anchor.' },
            { start: 80.04, end: 83.62, ko: '건강하고 따뜻한 나날 보내시기 바랍니다. 감사합니다.', zh: '祝大家度过健康又温暖的日子。谢谢。', zhEn: 'Wishing you all healthy and warm days. Thank you.' },
        ],
