    audioUrl: '/audio/radio/bear-night/bear-night-d15.mp3',
    subtitles: [
      { start: 0, end: 3.83, ko: '안녕, 꼬마 친구들. 곰 아저씨예요.', zh: '你好呀，小朋友们。我是熊大叔。', zhEn: 'Hello, little ones. I\'m Uncle Bear.' },
      { start: 4.23, end: 7.74, ko: '오늘도 이불 속에 폭 들어왔어요?', zh: '今天也钻进被子里了吗？', zhEn: 'Did you snuggle into your blanket today too?' },
      { start: 8.14, end: 11.12, ko: '눈을 살며시 감고 이야기를 들어요.', zh: '轻轻闭上眼睛，听故事吧。', zhEn: 'Close your eyes gently and listen to a story.' },
      { start: 11.52, end: 14.51, ko: '오늘은 옛날 속담을 하나 알려 줄게요.', zh: '今天给你们讲一句老话。', zhEn: 'Today, I\'ll tell you an old saying.' },
      { start: 14.91, end: 16.98, ko: '"고생 끝에 낙이 온다."', zh: '叫"고생 끝에 낙이 온다（苦尽甘来）"。', zhEn: 'It\'s called "고생 끝에 낙이 온다 (after hardship comes ease)."' },
      { start: 17.38, end: 21.5, ko: '힘든 일이 끝나면 좋은 날이 온다는 말이에요.', zh: '意思是辛苦过去以后，好日子就会来。', zhEn: 'It means that after hard times, good days will come.' },
      { start: 21.9, end: 25.46, ko: '숲속에 아기 너구리가 살았어요.', zh: '森林里住着一只小浣熊。', zhEn: 'A little raccoon lives in the forest.' },
      { start: 25.86, end: 29.78, ko: '아기 너구리는 밭에 씨앗을 심었어요.', zh: '小浣熊在田里种下了种子。', zhEn: 'The little raccoon planted seeds in the field.' },
      { start: 30.18, end: 32.83, ko: '매일 아침 물을 주러 갔어요.', zh: '每天早上都去浇水。', zhEn: 'Every morning, it goes to water them.' },
      { start: 33.23, end: 37.44, ko: '"빨리 자라라, 당근아." 하고 말했어요.', zh: '它说"快长大吧，胡萝卜"。', zhEn: 'It said, "Grow up fast, carrot."' },
      { start: 37.84, end: 42.15, ko: '그런데 싹이 좀처럼 나오지 않았어요.', zh: '可是芽儿一直不冒出来。', zhEn: 'But the sprout just wouldn\'t come out.' },
      { start: 42.55, end: 45.91, ko: '비도 오지 않아서 땅이 말랐어요.', zh: '也不下雨，土都干了。', zhEn: 'It didn\'t rain either, and the soil dried up.' },
      { start: 46.31, end: 50.14, ko: '아기 너구리는 조금 속상했어요.', zh: '小浣熊有点难过。', zhEn: 'Little raccoon was a bit sad.' },
      { start: 50.54, end: 53.52, ko: '그래도 물 주기를 포기하지 않았어요.', zh: '但它没有放弃浇水。', zhEn: 'But it didn\'t give up watering.' },
      { start: 53.92, end: 57.9, ko: '두더지 아저씨가 다가와서 물었어요.', zh: '鼹鼠大叔走过来问。', zhEn: 'Uncle mole came over and asked.' },
      { start: 58.3, end: 60.86, ko: '"너구리야, 힘들지 않니?"', zh: '"浣熊呀，累不累呀？"', zhEn: '"Raccoon, are you tired?"' },
      { start: 61.26, end: 64.9, ko: '"조금 힘들어요. 그래도 기다릴래요."', zh: '"有点累，不过我要等下去。"', zhEn: '"A little tired, but I\'ll keep waiting."' },
      { start: 65.3, end: 69.13, ko: '며칠 뒤 드디어 작은 싹이 나왔어요.', zh: '几天后，终于冒出了小芽。', zhEn: 'A few days later, a little sprout finally appeared.' },
      { start: 69.53, end: 72.47, ko: '초록색 잎이 방긋 인사했어요.', zh: '绿色的叶子笑盈盈地打招呼。', zhEn: 'The green leaves greeted with a smile.' },
      { start: 72.87, end: 76.47, ko: '아기 너구리는 폴짝폴짝 뛰었어요.', zh: '小浣熊高兴得蹦蹦跳跳。', zhEn: 'Little raccoon jumped for joy.' },
      { start: 76.87, end: 79.95, ko: '여름이 지나고 가을이 왔어요.', zh: '夏天过去，秋天来了。', zhEn: 'Summer passed, and autumn came.' },
      { start: 80.35, end: 83.33, ko: '밭에는 통통한 당근이 가득했어요.', zh: '田里长满了胖乎乎的胡萝卜。', zhEn: 'The field was full of plump carrots.' },
      { start: 83.73, end: 86.24, ko: '"우아, 정말 크고 달아요!"', zh: '"哇，又大又甜呢！"', zhEn: '"Wow, they\'re big and sweet!"' },
      { start: 86.64, end: 89.85, ko: '두더지 아저씨도 함께 기뻐했어요.', zh: '鼹鼠大叔也一起高兴。', zhEn: 'Uncle mole was happy too.' },
      { start: 90.25, end: 92.81, ko: '"네가 애쓴 덕분이란다."', zh: '"都是因为你努力呀。"', zhEn: '"It\'s all because you worked hard."' },
      { start: 93.21, end: 96.56, ko: '아기 너구리는 당근을 나눠 주었어요.', zh: '小浣熊把胡萝卜分给大家。', zhEn: 'Little raccoon shared the carrots with everyone.' },
      { start: 96.96, end: 99.9, ko: '친구들은 모두 고맙다고 했어요.', zh: '朋友们都说谢谢。', zhEn: 'All the friends said thank you.' },
      { start: 100.3, end: 103.85, ko: '그날 밤 너구리는 배부르게 잤어요.', zh: '那天晚上浣熊吃得饱饱地睡了。', zhEn: 'That night, raccoon slept with a full belly.' },
      { start: 104.25, end: 107.04, ko: '힘든 시간을 잘 참으면요.', zh: '只要好好忍过辛苦的日子。', zhEn: 'If you just endure the hard days.' },
      { start: 107.44, end: 110.33, ko: '이렇게 달콤한 날이 꼭 와요.', zh: '就一定会等到这样甜甜的一天。', zhEn: 'You\'ll surely see a sweet day like this.' },
      { start: 110.73, end: 114.56, ko: '그래서 "고생 끝에 낙이 온다"고 해요.', zh: '所以才说"苦尽甘来"呀。', zhEn: 'That\'s why they say "sweet comes after bitter."' },
      { start: 114.96, end: 118.18, ko: '꼬마 친구들도 오늘 애 많이 썼어요.', zh: '小朋友们今天也很努力啦。', zhEn: 'Kids, you worked hard today too.' },
      { start: 118.58, end: 122.04, ko: '이제 편안하게 눈을 감아요.', zh: '现在安心地闭上眼睛吧。', zhEn: 'Now close your eyes peacefully.' },
      { start: 122.44, end: 127.18, ko: '잘 자요, 꼬마 친구들. 좋은 꿈 꿔요.', zh: '晚安，小朋友们。做个好梦。', zhEn: 'Good night, kids. Sweet dreams.' },
    ],
    vocab: [
      { ko: '씨앗', pos: '명사', zh: '种子', zhEn: 'seed', example: '밭에 씨앗을 심어요.', exampleZh: '在田里种下种子。', exampleZhEn: 'Plant the seeds in the field.' },
      { ko: '싹', pos: '명사', zh: '芽', zhEn: 'sprout', example: '작은 싹이 나왔어요.', exampleZh: '冒出了小芽。', exampleZhEn: 'A little sprout came up.' },
      { ko: '참다', pos: '동사', zh: '忍耐', zhEn: 'Patience', example: '힘들어도 참아요.', exampleZh: '再累也忍住。', exampleZhEn: 'Endure even when it\'s hard.' },
      { ko: '포기하다', pos: '동사', zh: '放弃', zhEn: 'Give up', example: '쉽게 포기하지 않아요.', exampleZh: '不轻易放弃。', exampleZhEn: 'Don\'t give up easily.' },
      { ko: '당근', pos: '명사', zh: '胡萝卜', zhEn: 'Carrot', example: '당근이 아주 달아요.', exampleZh: '胡萝卜很甜。', exampleZhEn: 'The carrot is sweet.' },
      { ko: '애쓰다', pos: '동사', zh: '努力', zhEn: 'effort', example: '하루 종일 애썼어요.', exampleZh: '努力了一整天。', exampleZhEn: 'Worked hard all day.' },
      { ko: '나누다', pos: '동사', zh: '分享', zhEn: 'share', example: '친구와 나눠 먹어요.', exampleZh: '和朋友分着吃。', exampleZhEn: 'Share it with a friend.' },
      { ko: '통통하다', pos: '형용사', zh: '胖乎乎', zhEn: 'Plump', example: '당근이 통통해요.', exampleZh: '胡萝卜胖乎乎的。', exampleZhEn: 'The carrot is plump.' },
    ],
