    coverColor: 'purple',
    scheduleTime: '21:00',
    category: '이야기',
    audioUrl: '/audio/radio/bear-night/bear-night-d16.mp3',
    subtitles: [
      { start: 0, end: 3.46, ko: '안녕, 꼬마 친구들. 곰 아저씨예요.', zh: '你好呀，小朋友们。我是熊大叔。', zhEn: 'Hello, little ones. I\'m Uncle Bear.' },
      { start: 3.86, end: 7.32, ko: '포근한 밤이 조용히 내려왔어요.', zh: '温暖的夜晚静静地降临了。', zhEn: 'A warm night quietly fell.' },
      { start: 7.72, end: 10.89, ko: '따뜻한 이불을 목까지 덮어요.', zh: '把暖暖的被子盖到脖子。', zhEn: 'Pull the warm blanket up to your neck.' },
      { start: 11.29, end: 14.93, ko: '오늘도 속담 하나를 들려줄게요.', zh: '今天也给你们讲一句老话。', zhEn: 'Today, I\'ll tell you another old saying.' },
      { start: 15.33, end: 18.27, ko: '"열 번 찍어 안 넘어가는 나무 없다."', zh: '叫"열 번 찍어 안 넘어가는 나무 없다（砍十次没有不倒的树）"。', zhEn: 'It\'s called \'열 번 찍어 안 넘어가는 나무 없다\' (No tree falls without ten chops).' },
      { start: 18.67, end: 21.75, ko: '꾸준히 하면 안 되는 일이 없다는 말이에요.', zh: '意思是只要坚持，没有做不成的事。', zhEn: 'It means if you persist, nothing is impossible.' },
      { start: 22.15, end: 25.7, ko: '숲속에 아기 다람쥐가 살았어요.', zh: '森林里住着一只小松鼠。', zhEn: 'A little squirrel lived in the forest.' },
      { start: 26.1, end: 29.56, ko: '다람쥐는 커다란 호두를 하나 주웠어요.', zh: '松鼠捡到了一颗大大的核桃。', zhEn: 'The squirrel found a big walnut.' },
      { start: 29.96, end: 32.56, ko: '그런데 껍질이 너무 딱딱했어요.', zh: '可是壳太硬了。', zhEn: 'But the shell was too hard.' },
      { start: 32.96, end: 35.61, ko: '앞니로 톡톡 두드려 봤어요.', zh: '用门牙咚咚地敲了敲。', zhEn: 'It tapped it with its front teeth, knock knock.' },
      { start: 36.01, end: 38.85, ko: '그래도 호두는 꿈쩍도 안 했어요.', zh: '可核桃一动也不动。', zhEn: 'But the walnut didn\'t budge.' },
      { start: 39.25, end: 43.28, ko: '"에잇, 안 열리네." 하고 한숨 쉬었어요.', zh: '"唉，打不开呀"，它叹了口气。', zhEn: '\'Oh, I can\'t open it,\' it sighed.' },
      { start: 43.68, end: 46.67, ko: '옆에서 고슴도치가 지켜봤어요.', zh: '旁边的刺猬看着它。', zhEn: 'A hedgehog nearby watched it.' },
      { start: 47.07, end: 49.39, ko: '"포기하지 말고 다시 해 봐."', zh: '"别放弃，再试试看。"', zhEn: '\'Don\'t give up, try again.\'' },
      { start: 49.79, end: 53.43, ko: '다람쥐는 다시 톡톡 두드렸어요.', zh: '松鼠又咚咚地敲起来。', zhEn: 'The squirrel knocked again, knock knock.' },
      { start: 53.83, end: 58.05, ko: '한 번, 두 번, 세 번 두드렸어요.', zh: '敲了一次、两次、三次。', zhEn: 'It knocked once, twice, three times.' },
      { start: 58.45, end: 61.91, ko: '껍질에 아주 작은 금이 갔어요.', zh: '壳上出现了一道小小的裂纹。', zhEn: 'A small crack appeared on the shell.' },
      { start: 62.31, end: 65.2, ko: '"어? 조금 갈라졌어요!"', zh: '"咦？裂开一点点了！"', zhEn: '"Huh? It\'s cracking a little!"' },
      { start: 65.6, end: 69.15, ko: '다람쥐는 신이 나서 또 두드렸어요.', zh: '松鼠来了劲，又敲起来。', zhEn: 'The squirrel got motivated and started knocking again.' },
      { start: 69.55, end: 74.43, ko: '네 번, 다섯 번, 여섯 번 두드렸어요.', zh: '敲了四次、五次、六次。', zhEn: 'It knocked four, five, six times.' },
      { start: 74.83, end: 77.81, ko: '금이 점점 크게 벌어졌어요.', zh: '裂纹渐渐变大了。', zhEn: 'The crack gradually grew bigger.' },
      { start: 78.21, end: 81.1, ko: '이마에 땀이 송골송골 맺혔어요.', zh: '额头上冒出了细细的汗珠。', zhEn: 'Fine beads of sweat appeared on its forehead.' },
      { start: 81.5, end: 84.39, ko: '그래도 다람쥐는 멈추지 않았어요.', zh: '但松鼠没有停下来。', zhEn: 'But the squirrel didn\'t stop.' },
      { start: 84.79, end: 87.53, ko: '열 번째로 힘껏 두드렸어요.', zh: '第十次使劲敲了下去。', zhEn: 'On the tenth try, it knocked hard.' },
      { start: 87.93, end: 91.39, ko: '"딱!" 하고 호두가 쪼개졌어요.', zh: '"咔"的一声，核桃裂开了。', zhEn: 'With a "crack," the walnut split open.' },
      { start: 91.79, end: 95.53, ko: '안에는 고소한 알맹이가 가득했어요.', zh: '里面满是香香的果仁。', zhEn: 'Inside was full of fragrant nutmeat.' },
      { start: 95.93, end: 98.78, ko: '"우아, 드디어 열렸어요!"', zh: '"哇，终于打开啦！"', zhEn: '"Wow, finally opened it!"' },
      { start: 99.18, end: 103.05, ko: '고슴도치와 알맹이를 나눠 먹었어요.', zh: '它和刺猬分着吃了果仁。', zhEn: 'It shared the nutmeat with the hedgehog.' },
      { start: 103.45, end: 105.53, ko: '아무리 딱딱한 호두도요.', zh: '再硬的核桃也一样。', zhEn: 'No matter how hard the walnut is.' },
      { start: 105.93, end: 108.49, ko: '꾸준히 두드리면 꼭 열려요.', zh: '只要坚持敲，就一定能打开。', zhEn: 'As long as you keep knocking, you\'ll definitely open it.' },
      { start: 108.89, end: 114.1, ko: '그래서 "열 번 찍어 안 넘어가는 나무 없다"고 해요.', zh: '所以才说"砍十次没有不倒的树"。', zhEn: 'That\'s why they say, "Strike ten times, and no tree will stand."' },
      { start: 114.5, end: 118.71, ko: '꼬마 친구들도 포기하지 않는 마음, 참 예뻐요.', zh: '小朋友们不放弃的心，真可爱。', zhEn: 'The children\'s never-give-up hearts are truly adorable.' },
      { start: 119.11, end: 121.71, ko: '이제 손을 스르르 풀고 쉬어요.', zh: '现在把手轻轻松开，休息吧。', zhEn: 'Now gently let go and rest.' },
      { start: 122.11, end: 126.28, ko: '잘 자요, 꼬마 친구들. 좋은 꿈 꿔요.', zh: '晚安，小朋友们。做个好梦。', zhEn: 'Good night, kids. Sweet dreams.' },
    ],
