        "start": 340.53,
        "end": 345.51,
        "speaker": "host",
        "ko": "여우의 인터뷰 카페였습니다. 오늘도 수고 많으셨어요.",
        "zh": "这里是狐狸的访谈咖啡馆。今天也辛苦了。"
